:root{--homepage-gap:calc(var(--site-gap) * 2)}
.site-header>.container-xxl,.site-main>.container-xxl,.site-footer>.container-xxl{max-width:100%;padding-left:var(--homepage-gap)!important;padding-right:var(--homepage-gap)!important}
.site-main>.container-xxl{padding-top:var(--homepage-gap)!important;padding-bottom:0!important}
section[name=body].content{display:block;margin:0;padding:0;border:none;box-shadow:none;background:transparent}
.public-page,.public-flow{display:flex;flex-direction:column;gap:var(--homepage-gap);margin:0;padding:0}
.public-flow-section,.public-section-flow{display:block;margin:0;padding:0}
.public-section-frame{display:block;width:100%;margin:0;padding:var(--homepage-gap)}
.public-flow-section>.public-section-frame>.row,.public-flow-section>.public-section-frame>.public-grid{margin:0;--bs-gutter-x:var(--homepage-gap);--bs-gutter-y:var(--homepage-gap);row-gap:var(--homepage-gap);align-items:start}
.public-flow-section>.public-section-frame>.row>[class*="col-"]{display:flex;flex-direction:column;padding-left:0;padding-right:0}

.public-flow-section .public-card,.public-flow-section .accordion .accordion-item{padding:var(--homepage-gap);box-shadow:var(--site-shadow);border:var(--site-border);border-radius:var(--site-radius);background:var(--site-surface)}
.public-section-copy,.public-card,.public-contact-panel,.public-contact-card{display:flex;flex-direction:column;gap:var(--homepage-gap)}
.public-section-copy>* ,.public-card>* ,.public-contact-panel>* ,.public-contact-card>*{margin:0}




.public-actions,.public-contact-actions{display:flex;flex-wrap:wrap;gap:var(--homepage-gap);align-items:flex-start;margin:0}
.public-grid,.public-accordion,.public-contact-details{gap:var(--homepage-gap)}
