/* Detailed navigation. */

.docs-sidebar-inner{display:flex;flex-direction:column;gap:calc(var(--site-gap) * 1.5)}
.component[name=DetailedNav]{margin:0!important;border:none!important;box-shadow:none!important;background:transparent!important;height:auto!important}
.docs-nav-grid{display:grid;gap:calc(var(--site-gap) * 2);grid-template-columns:minmax(0,1fr);align-items:stretch}
.docs-nav-grid[data-columns="2"]{grid-template-columns:repeat(2,minmax(0,1fr))}
.docs-nav-grid[data-columns="3"]{grid-template-columns:repeat(3,minmax(0,1fr))}
.docs-nav-card{display:flex;flex-direction:column;gap:var(--site-gap);padding:calc(var(--site-gap) * 1.5);border:var(--site-border);box-shadow:var(--site-shadow);background:var(--site-surface)}
.docs-nav-card p{margin:0;max-width:none}
@media (max-width:1199.98px){.docs-nav-grid[data-columns="3"]{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:767.98px){.docs-nav-grid[data-columns="2"],.docs-nav-grid[data-columns="3"]{grid-template-columns:1fr}}
@media (max-width:991.98px){.docs-sidebar{position:static;top:auto}}

.docs-nav-scope-grid {
  gap: 1.25rem;
}

.docs-nav-scope {
  position: relative;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  padding: 1.35rem 1.4rem 1.2rem 1.65rem;
  border: 1px solid rgba(20, 42, 72, .16);
  border-left: 3px solid #0e6fae;
  border-radius: 6px;
  background: #fff;
  box-shadow: 0 8px 20px rgba(20, 42, 72, .07);
  transition: transform .18s ease, border-color .18s ease, box-shadow .18s ease;
}

.docs-nav-scope:hover {
  transform: translateY(-2px);
  border-color: rgba(14, 111, 174, .42);
  box-shadow: 0 12px 26px rgba(20, 42, 72, .11);
}

.docs-nav-title {
  margin: 0 0 .75rem;
  font-family: inherit;
  font-size: 1.05rem;
  line-height: 1.35;
}

.docs-nav-title a {
  color: #142a48;
  text-decoration: none;
}

.docs-nav-title a:hover,
.docs-nav-title a:focus-visible {
  color: #0e6fae;
  text-decoration: underline;
  text-underline-offset: .2em;
}

.docs-nav-description {
  flex: 1 1 auto;
  margin: 0 0 1rem 1.2rem;
  color: #40576b;
}

.docs-nav-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 2rem;
  margin-top: auto;
  padding-left: .15rem;
}

.docs-nav-actions {
  position: relative;
  z-index: 2;
  display: flex;
  justify-content: flex-end;
  align-items: flex-end;
  width: 100%;
  margin-top: auto;
  margin-left: auto;
  padding-top: calc(var(--site-gap) * 1.5);
  padding-right: 0;
}

.docs-nav-command {
  display: inline-flex;
  align-items: center;
  gap: .08rem;
  padding: .42rem .68rem;
  border: 1px solid rgba(14, 111, 174, .28);
  border-radius: 4px;
  background: #f2f9fd;
  color: #0e6fae;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace;
  font-size: var(--bs-body-font-size);
  font-weight: 700;
  line-height: 1;
  text-decoration: none;
}

.docs-nav-command-call { color: #6542a6; }
.docs-nav-command-arrow {
  margin-left: .38rem;
  transition: transform .18s ease;
}

.docs-nav-command:hover,
.docs-nav-command:focus-visible {
  border-color: #0e6fae;
  background: #e4f4fd;
  color: #0b5788;
  text-decoration: none;
}

.docs-nav-command:hover .docs-nav-command-arrow,
.docs-nav-command:focus-visible .docs-nav-command-arrow {
  transform: translateX(3px);
}

@media (max-width: 575.98px) {
  .docs-nav-scope { padding-left: 1.25rem; }
  .docs-nav-description,
  .docs-nav-actions { margin-left: 0; }
}

/* Documentation image semantics. */
.semantic-image-block{display:block;max-width:100%;margin:calc(var(--site-gap) * 2) 0;padding-left:var(--ccoder-code-indent)}
.semantic-image-block::before,.semantic-image-block::after{display:block;margin-left:calc(var(--ccoder-code-indent) * -1);color:var(--ccoder-semantic-blue);font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,"Liberation Mono",monospace;font-size:var(--ccoder-brace-size);font-weight:700;line-height:1}
.semantic-image-block::before{content:"{";margin-bottom:.5rem}
.semantic-image-block::after{content:"}";margin-top:.5rem}
.semantic-image-block>img{margin:0!important}
p.semantic-image-host{max-width:none;margin:0;padding-left:0}
p.semantic-image-host::before,p.semantic-image-host::after{content:none}

/* Quiet heading weight and baseline-aligned inline semantics. */
h1{font-weight:400!important}h2,h3,h4,h5,h6{font-weight:700!important}
h1::before,h1::after,h2::before,h2::after,h3::before,h3::after,h4::before,h4::after,h5::before,h5::after,h6::before,h6::after,.docs-nav-title::before,.docs-nav-title::after{font-weight:400}
h2,h3,h4,h5,h6,.docs-nav-title{align-items:center}
h1::before,h1::after,h2::before,h2::after,h3::before,h3::after,h4::before,h4::after,h5::before,h5::after,h6::before,h6::after,.docs-nav-title::before,.docs-nav-title::after{align-self:center;vertical-align:middle;line-height:1;transform:none}

/* Tri-nature architecture diagram. */
.tri-nature-diagram{display:flex;flex-direction:column;align-items:center;gap:0;width:100%;margin:calc(var(--site-gap)*2) 0;padding:calc(var(--site-gap)*2);border:var(--site-border);border-radius:var(--site-radius);background:linear-gradient(145deg,#f8fcff 0%,#edf7fd 100%);box-shadow:var(--site-shadow)}
.tri-nature-diagram figcaption{width:100%;margin:0 0 calc(var(--site-gap)*2);color:var(--site-primary);font-size:1.15rem;font-weight:700;text-align:center}
.tri-nature-consumer,.tri-nature-layer,.tri-nature-fractal-note{box-sizing:border-box;width:min(100%,760px);padding:calc(var(--site-gap)*1.5);border:1px solid rgba(14,111,174,.28);border-radius:var(--site-radius);background:var(--site-surface);text-align:center}
.tri-nature-consumer,.tri-nature-layer{display:grid;grid-template-columns:minmax(100px,.32fr) minmax(130px,.38fr) minmax(220px,1fr);align-items:center;gap:var(--site-gap)}
.tri-nature-consumer{width:min(92%,680px);border-style:dashed}
.tri-nature-consumer>span,.tri-nature-layer>span:last-child,.tri-nature-fractal-note>span{color:color-mix(in srgb,var(--site-ink) 78%,white 22%)}
.tri-nature-role{justify-self:start;padding:.35rem .65rem;border-radius:999px;background:var(--site-primary);color:white;font-weight:700;text-transform:uppercase;letter-spacing:.06em}
.tri-nature-layer>strong,.tri-nature-consumer>strong{color:var(--site-primary);font-size:1.08rem}
.tri-nature-exposure{border-left:6px solid #142a48}
.tri-nature-purpose{border-left:6px solid #0e6fae}
.tri-nature-dependency{border-left:6px solid #52bcff}
.tri-nature-connector{position:relative;display:flex;align-items:center;justify-content:center;width:3px;height:54px;background:linear-gradient(var(--site-secondary),var(--site-primary))}
.tri-nature-connector::after{content:"";position:absolute;bottom:-1px;width:11px;height:11px;border-right:3px solid var(--site-primary);border-bottom:3px solid var(--site-primary);transform:rotate(45deg)}
.tri-nature-connector>span{position:absolute;left:14px;padding:.1rem .4rem;background:#f2f9fd;color:var(--site-secondary);font-size:var(--bs-body-font-size);white-space:nowrap}
.tri-nature-fractal-note{display:flex;flex-direction:column;gap:var(--site-gap);margin-top:calc(var(--site-gap)*2);border-color:rgba(101,66,166,.32);background:#f8f5ff}
.tri-nature-fractal-note>strong{color:#6542a6}
@media (max-width:767.98px){.tri-nature-diagram{padding:var(--site-gap)}.tri-nature-consumer,.tri-nature-layer{grid-template-columns:1fr;text-align:left}.tri-nature-role{justify-self:start}.tri-nature-connector>span{left:12px}}.public-grid-three{grid-template-columns:repeat(3,minmax(0,1fr))}@media (max-width:991.98px){.public-grid-three{grid-template-columns:repeat(2,minmax(0,1fr))}}@media (max-width:575.98px){.public-grid-three{grid-template-columns:1fr}}.site-main h1{margin-top:0}.site-main h2,.site-main h3,.site-main h4,.site-main h5,.site-main h6{margin-top:calc(var(--site-gap)*2)}/* Semantic content lists. */
.public-article ol,.public-article ul,.docs-content ol,.docs-content ul{display:block;padding-left:calc(var(--ccoder-code-indent) + 1.75rem)}
.public-article ol::before,.public-article ol::after,.public-article ul::before,.public-article ul::after,.docs-content ol::before,.docs-content ol::after,.docs-content ul::before,.docs-content ul::after{display:block;margin-left:calc((var(--ccoder-code-indent) + 1.75rem)*-1);color:var(--ccoder-semantic-blue);font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,"Liberation Mono",monospace;font-size:var(--ccoder-brace-size);font-weight:400;line-height:1}
.public-article ol::before,.public-article ul::before,.docs-content ol::before,.docs-content ul::before{content:"{";margin-bottom:.3rem}
